  "check_code": "import re
import sqlite3
import unicodedata
from pathlib import Path


SYSTEM = "kingdee_receivables_collection"
ALLOCATION_ID = "RA-2025-0114-009"
RECEIPT_ID = "BR-SZ-2024-9999-404"
CHARGE_ORDER_ID = "POS-BQ-2024-1222"
CUSTOMER_ID = "CUST_BLLY_001"
HOTEL_ID = "HOTEL_SZ_BLLY_001"
EXPECTED_DATE = "2025-01-17"


def _paths(ws):
    database = Path(ws).resolve().parent / "system" / SYSTEM / "state.db"
    baseline = database.with_name("state.db.pinned_backup")
    return database, baseline


def _norm(value):
    text = unicodedata.normalize("NFKC", "" if value is None else str(value)).lower()
    return re.sub(r"[\s\W_]+", "", text, flags=re.UNICODE)


def _target_tasks(database):
    with sqlite3.connect(database) as connection:
        connection.row_factory = sqlite3.Row
        rows = connection.execute(
            "SELECT * FROM collection_tasks WHERE charge_order_id = ? ORDER BY task_id",
            (CHARGE_ORDER_ID,),
        ).fetchall()
    return [dict(row) for row in rows]


def _has_amount(text):
    return bool(re.search(r"(?<!\d)25[\s,，]*000(?:\.00)?(?!\d)", text or ""))


def check_followup_task_post_state(ws):
    database, _ = _paths(ws)
    if not database.exists():
        return {"score": 0, "detail": "Kingdee state database is missing"}
    rows = _target_tasks(database)
    if len(rows) != 1:
        return {"score": 0, "detail": f"Expected one target-order task, found {len(rows)}"}
    row = rows[0]
    owner = _norm(row["owner_department"])
    required = _norm(row["required_document"])
    note = _norm(row["task_note"])
    owner_ok = "财务应收" in owner and ("餐饮销售" in owner or "销售收款" in owner)
    evidence_ok = (
        ("银行回单" in required or "银行收款回单" in required)
        and ("真实入账流水" in required or ("入账" in required and "流水" in required))
        and "核销归属" in required
    )
    restriction_ok = (
        ("财务复核" in note or "财务应收复核" in note)
        and ("不得认领" in note or "禁止认领" in note or "暂不认领" in note)
        and "核销" in note
    )
    identity_ok = ALLOCATION_ID.lower() in (row["task_note"] or "").lower()
    ok = all(
        [
            row["customer_id"] == CUSTOMER_ID,
            "宝利来实业" in _norm(row["customer_name"]),
            row["hotel_id"] == HOTEL_ID,
            row["task_type"] == "overdue_receivable",
            row["task_status"] == "open",
            row["first_contact_date"] == EXPECTED_DATE,
            row["promised_payment_date"] is None,
            owner_ok,
            evidence_ok,
            restriction_ok,
            identity_ok,
            _has_amount(row["task_note"]),
        ]
    )
    if ok:
        return {"score": 1, "detail": "The orphan follow-up task has the required open post-state and evidence controls"}
    return {
        "score": 0,
        "detail": (
            "Target task fields or semantic controls are incomplete: "
            f"customer={row['customer_id']}, hotel={row['hotel_id']}, type={row['task_type']}, "
            f"status={row['task_status']}, date={row['first_contact_date']}, promised={row['promised_payment_date']}, "
            f"owner_ok={owner_ok}, evidence_ok={evidence_ok}, restriction_ok={restriction_ok}, "
            f"identity_ok={identity_ok}, amount_ok={_has_amount(row['task_note'])}"
        ),
    }


def check_idempotent_singleton(ws):
    database, _ = _paths(ws)
    if not database.exists():
        return {"score": 0, "detail": "Kingdee state database is missing"}
    rows = _target_tasks(database)
    if len(rows) != 1:
        return {"score": 0, "detail": f"Expected exactly one target-order task after idempotent submission, found {len(rows)}"}
    markers = re.findall(r"\[idempotency_key:([^\]]+)\]", rows[0]["task_note"] or "", flags=re.IGNORECASE)
    if len(markers) == 1 and ALLOCATION_ID.lower() in markers[0].lower():
        return {"score": 1, "detail": "One task exists and its sole idempotency key binds to the orphan allocation"}
    return {"score": 0, "detail": f"Expected one allocation-bound idempotency marker, found {markers}"}


def check_original_allocation_preserved(ws):
    database, baseline = _paths(ws)
    if not database.exists() or not baseline.exists():
        return {"score": 0, "detail": "Kingdee current or pinned baseline database is missing"}
    with sqlite3.connect(database) as current, sqlite3.connect(baseline) as before:
        current_row = current.execute(
            "SELECT * FROM receipt_allocations WHERE allocation_id = ?", (ALLOCATION_ID,)
        ).fetchone()
        baseline_row = before.execute(
            "SELECT * FROM receipt_allocations WHERE allocation_id = ?", (ALLOCATION_ID,)
        ).fetchone()
        fake_receipt = current.execute(
            "SELECT 1 FROM bank_receipts WHERE receipt_id = ?", (RECEIPT_ID,)
        ).fetchone()
    if current_row == baseline_row and current_row is not None and fake_receipt is None:
        return {"score": 1, "detail": "Original allocation is unchanged and the nonexistent receipt was not fabricated"}
    return {"score": 0, "detail": "Original allocation changed, disappeared, or a fake receipt was inserted"}


def check_existing_tasks_preserved(ws):
    database, baseline = _paths(ws)
    if not database.exists() or not baseline.exists():
        return {"score": 0, "detail": "Kingdee current or pinned baseline database is missing"}
    with sqlite3.connect(database) as current, sqlite3.connect(baseline) as before:
        before_rows = before.execute("SELECT * FROM collection_tasks ORDER BY task_id").fetchall()
        current_by_id = {
            row[0]: row
            for row in current.execute("SELECT * FROM collection_tasks ORDER BY task_id").fetchall()
        }
    changed = [row[0] for row in before_rows if current_by_id.get(row[0]) != row]
    if not changed:
        return {"score": 1, "detail": "All pre-existing collection tasks remain present and unchanged"}
    return {"score": 0, "detail": f"Pre-existing collection tasks changed or disappeared: {changed}"}
